package com.agacostays.payroll.event.producer; import com.agacostays.payroll.constants.KafkaTopicConstants; import com.agacostays.payroll.event.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component; @Component public class PayrollEventProducer{private final KafkaTemplate<String,Object> kafka;public PayrollEventProducer(KafkaTemplate<String,Object> k){kafka=k;}public void generated(PayrollGeneratedEvent e){kafka.send(KafkaTopicConstants.PAYROLL_EVENTS,String.valueOf(e.payrollId()),e);}public void credited(SalaryCreditedEvent e){kafka.send(KafkaTopicConstants.PAYROLL_EVENTS,String.valueOf(e.payrollId()),e);}public void failed(SalaryPaymentFailedEvent e){kafka.send(KafkaTopicConstants.PAYROLL_EVENTS,String.valueOf(e.payrollId()),e);}public void slipGenerated(SalarySlipGeneratedEvent e){kafka.send(KafkaTopicConstants.PAYROLL_EVENTS,String.valueOf(e.payrollId()),e);}}